static LineNum lastLineNum(UPSAgreementId _agreementId)
{
    return (select maxof(LineNum) from UPSPriceTermJournalTrans
        index hint TransIdx
        where UPSPriceTermJournalTrans.AgreementId == _agreementId).LineNum;
}

/// <summary>
/// Initiates the current table buffer by using the specified table buffer.
/// </summary>
/// <param name="_upsPriceTermJournalTable">
/// A <c>UPSPriceTermJournalTable</c> table buffer.
/// </param>
public void initfromUPSPriceTermJournalTable(UPSPriceTermJournalTable _upsPriceTermJournalTable)
{
    this.AgreementId = _upsPriceTermJournalTable.AgreementId;

    InventDim inventDimSite;
    inventDimSite.InventSiteId = _upsPriceTermJournalTable.InventSiteId;
    inventDimSite = InventDim::findOrCreate(inventDimSite);
    this.InventDimId = inventDimSite.InventDimId;

    this.TransDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
}

/// <summary>
/// Initiates the current table buffer by using the specified table buffer.
/// </summary>
/// <param name="_upsPriceTermJournalTrans">
/// A <c>UPSPriceTermJournalTrans</c> table buffer.
/// </param>
public void initfromUPSPriceTermJournalTrans(UPSPriceTermJournalTrans _upsPriceTermJournalTrans)
{
    this.AgreementId                    = _upsPriceTermJournalTrans.AgreementId;
    this.CompoundCalculationBasis       = _upsPriceTermJournalTrans.CompoundCalculationBasis;
    this.Code                           = _upsPriceTermJournalTrans.Code;
    this.Value                          = _upsPriceTermJournalTrans.Value;
    this.LineNum                        = UPSPriceTermJournalTrans::lastLineNum(_upsPriceTermJournalTrans.AgreementId) + 1;
    this.InventDimId                    = _upsPriceTermJournalTrans.InventDimId;
    this.UnitId                         = _upsPriceTermJournalTrans.UnitId;
}

public static void lookupCode(FormStringControl _control,
                              PriceDiscAccountCode _accountCode = TableGroupAll::All,
                              PriceDiscAccountRelation _accountRelation = null)
{
    Query query = new Query();
    QueryBuildDataSource queryBuildDataSource;
    QueryBuildRange qbrAccountRelation;
    QueryBuildRange qbrAccountCode;
    SysTableLookup sysTableLookup;

    sysTableLookup = SysTableLookup::newParameters(tableNum(UPSPriceTermTable),_control,true);
    sysTableLookup.parmUseLookupValue(false);
    sysTableLookup.addLookupfield(fieldNum(UPSPriceTermTable, Code));
    sysTableLookup.addLookupfield(fieldNum(UPSPriceTermTable, Description));
    queryBuildDataSource = query.addDataSource(tableNum(UPSPriceTermTable));
    queryBuildDataSource.addSortField(fieldnum(UPSPriceTermTable,Code ));

    if (_accountRelation)
    {
        qbrAccountRelation = queryBuildDataSource.addRange(fieldNum(UPSPriceTermTable, AccountRelation));
        qbrAccountRelation.value(_accountRelation);
        qbrAccountCode = queryBuildDataSource.addRange(fieldNum(UPSPriceTermTable, AccountCode));
        qbrAccountCode.value(queryValue(_accountCode));
    }

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

static UPSPriceTermJournalTrans find(UPSAgreementId     _agreementId,
                                     LineNum            _lineNum = 0,
                                     boolean            _update  = false)
{
    UPSPriceTermJournalTrans upsPriceTermJournalTrans;

    if (_agreementId)
    {
        if (_update)
        {
            upsPriceTermJournalTrans.selectForUpdate(_update);
        }
        if (_lineNum)
        {
            select firstonly upsPriceTermJournalTrans
                index hint TransIdx
                where upsPriceTermJournalTrans.AgreementId  == _agreementId
                &&    upsPriceTermJournalTrans.LineNum      == _lineNum;
        }
        else
        {
            select firstonly upsPriceTermJournalTrans
                index hint TransIdx
                where upsPriceTermJournalTrans.AgreementId == _agreementId;
        }
    }

    return upsPriceTermJournalTrans;
}

    static boolean exist(UPSAgreementId     _agreementId,
                          LineNum           _lineNum = naReal())
    {
        if (!_agreementId)
        {
            return false;
        }

        if (_lineNum == naReal())
        {
            return (select firstonly RecId from upsPriceTermJournalTrans
                        index hint TransIdx
                        where upsPriceTermJournalTrans.AgreementId == _agreementId).RecId != 0;
        }

        return (select firstonly RecId from upsPriceTermJournalTrans
                    index hint TransIdx
                    where upsPriceTermJournalTrans.AgreementId == _agreementId
                    &&    upsPriceTermJournalTrans.LineNum     == _lineNum).RecId != 0;
	}

public void write()
{
    if (this.PricingRule && !this.upsPricingRule().PriceAttributeGroup)
    {
        UPSPricingRule::find(this.PricingRule, true).delete();
        this.PricingRule = 0;
    }

    super();
}
